# RUN THE PIPELINE (started by a launcher such as RUN_posthoc_medium.R; you do not edit this file)
# Base R only (plus the rpart package that ships with R). Runs, in this order:
#   1  the explorer script of each family chosen (explore_<family>.R)
#   2  analyze_explorer.R   (drivers, rules, held-out checks, observable-only rules)
#   3  plot_explorer.R      (the per-test plots)
#   4  evaluate_selectors.R and make_paper_figures.R (only when "anova" is chosen), or make_figure5.R
#      (only when "posthoc" is chosen)
#   5  check_hypotheses.R   (the pre-stated criteria of Appendix B, with a verdict for each; new in 1.5)
#   6  collect_results.R    (one flat folder plus one uniquely named zip to upload, with RUN_INFO.txt)
# REANALYSE = TRUE (set by RUN_anova_full_reanalyse.R) skips the simulation and the model-based analysis
# and redoes only the REPORTING steps (selectors, figures, hypothesis checks, package) from the saved
# results. It needs the finished results and never simulates anything.
# BEFORE step 1 it checks that every script in this folder is exactly the installed toolkit version
# (MANIFEST.csv), and it stops with a plain message if not, so mixed versions can never run.
# It stops at the first problem and says which step failed. If a run is interrupted, start the same
# launcher again: finished work is restored from checkpoints.
# Settings (FAMILIES, MODE, COLLECT) come from the launcher; the defaults below apply only if none is set.
# If an explorer finds results from an OLDER code version with the same settings, it archives that
# folder (renames it, never deletes it) and starts a fresh run.

SCRIPT_DIR <- tryCatch(dirname(normalizePath(sys.frame(1)$ofile, winslash = "/")),   # the folder of the launcher that started it
                       error = function(e) "N:/paper-simulation-explorer/R")
if (!exists("FAMILIES")) FAMILIES <- "posthoc"   # any of: "correlation", "twogroup", "anova", "chisq", "posthoc"
if (!exists("MODE")) MODE <- "medium"            # "pilot" (quick check), "medium" or "full"
if (!exists("COLLECT")) COLLECT <- TRUE          # TRUE = finish with the upload package
if (!exists("REANALYSE")) REANALYSE <- FALSE     # TRUE = reporting steps only, from saved results (no simulation)

verify_toolkit <- function(dir) {
  if (identical(Sys.getenv("SIM_SKIP_CHECK"), "1")) return(invisible("skipped"))
  manifest <- file.path(dir, "MANIFEST.csv")
  if (!file.exists(manifest))
    stop("MANIFEST.csv is missing from ", dir, ".\nThis folder is not an installed toolkit. Run the installer again (see README.txt).", call. = FALSE)
  m <- read.csv(manifest, stringsAsFactors = FALSE)
  actual <- unname(tools::md5sum(file.path(dir, m$file)))
  bad <- m$file[is.na(actual) | actual != m$md5]
  if (length(bad))
    stop("These files in ", dir, " are missing or are not the installed version:\n  ", paste(bad, collapse = ", "),
         "\nRun the installer again to restore them (see README.txt).\n(If you changed a file on purpose, run  Sys.setenv(SIM_SKIP_CHECK = \"1\")  first.)", call. = FALSE)
  version <- if (file.exists(file.path(dir, "VERSION.txt"))) readLines(file.path(dir, "VERSION.txt"), warn = FALSE)[1] else "unknown"
  invisible(version)
}

run_pipeline <- function() {
  on.exit(suppressWarnings(rm(list = intersect(c("FAMILIES", "MODE", "COLLECT", "REANALYSE"), ls(globalenv())), envir = globalenv())), add = TRUE)
  if (!MODE %in% c("pilot", "medium", "full")) stop('MODE must be "pilot", "medium" or "full"', call. = FALSE)
  bad <- setdiff(FAMILIES, c("correlation", "twogroup", "anova", "chisq", "posthoc"))
  if (length(bad)) stop("Unknown family: ", paste(bad, collapse = ", "), call. = FALSE)
  if (!dir.exists(SCRIPT_DIR)) stop("SCRIPT_DIR not found: ", SCRIPT_DIR, call. = FALSE)
  version <- verify_toolkit(SCRIPT_DIR)
  if (isTRUE(REANALYSE)) {
    root <- Sys.getenv("SIM_OUTPUT_ROOT", unset = "N:/paper-simulation-explorer")
    for (f in FAMILIES) {
      d <- file.path(root, paste0(f, "_", MODE))
      need <- file.path(d, c(sprintf("explore_%s_train.csv", f), sprintf("explore_%s_test.csv", f), file.path("analysis", "analysis_validation.csv")))
      if (!all(file.exists(need))) stop("Nothing to rebuild: the finished ", f, " ", MODE, " results were not found in ", d,
                                        ". This option only redraws a run that has already finished.", call. = FALSE)
    }
  }
  steps <- c(if (!isTRUE(REANALYSE)) c(sprintf("explore_%s.R", FAMILIES), "analyze_explorer.R", "plot_explorer.R"),
             if ("anova" %in% FAMILIES) c("evaluate_selectors.R", "make_paper_figures.R"),
             if ("posthoc" %in% FAMILIES) "make_figure5.R",
             if (any(c("anova", "posthoc") %in% FAMILIES)) "check_hypotheses.R",
             if (COLLECT) "collect_results.R")
  missing <- steps[!file.exists(file.path(SCRIPT_DIR, steps))]
  if (length(missing)) stop("Not found in ", SCRIPT_DIR, ": ", paste(missing, collapse = ", "), call. = FALSE)
  Sys.setenv(SIM_MODE = MODE, SIM_FAMILIES = paste(FAMILIES, collapse = ","))
  cat(sprintf("Toolkit version %s: all scripts verified.\n", version))
  cat(sprintf("Running %d steps in %s mode%s: %s\n", length(steps), toupper(MODE), if (isTRUE(REANALYSE)) " (REBUILD FROM SAVED RESULTS, no simulation)" else "", paste(steps, collapse = " -> ")))
  started <- Sys.time()
  for (i in seq_along(steps)) {
    cat(sprintf("\n========== step %d of %d: %s (%.1f minutes so far) ==========\n", i, length(steps), steps[i],
                as.numeric(difftime(Sys.time(), started, units = "mins"))))
    ok <- tryCatch({ source(file.path(SCRIPT_DIR, steps[i]), local = FALSE, echo = FALSE); TRUE },
                   error = function(e) { cat("\nSTEP FAILED:", steps[i], "\n", conditionMessage(e), "\n"); FALSE })
    if (!ok) stop("The pipeline stopped at ", steps[i], ". Start the same launcher again after fixing that; finished work is kept.", call. = FALSE)
  }
  cat(sprintf("\nPipeline finished in %.1f minutes.\n", as.numeric(difftime(Sys.time(), started, units = "mins"))))
}
# The whole sequence runs inside run_pipeline(), so a problem stops it cleanly.
run_pipeline()
